import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { environment } from '../../../../environments/environment';
import { RouterLink } from "@angular/router";
import { ToastService } from '../../../common/toast.service';

@Component({
  selector: 'app-consultation',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './consultation.component.html',
  styleUrl: './consultation.component.scss'
})
export class ConsultationComponent implements OnInit {

  eventsList: any[] = [];

  constructor(private http: HttpClient, private toastService: ToastService) { }

  ngOnInit(): void {
    this.getConsultations();
  }

  getConsultations() {
    this.http.get<any>(`${environment.apiUrl}/consultation`)
      .subscribe({
        next: (res) => {

          const consultations = res.data;

          this.eventsList = consultations.map((event: any) => ({
            id: event.id,
            title: event.name,
            date: event.launchAt,
            location: 'Online',
            endDate: event.endAt,
            hasDocument: event.hasDocument
          }));
          this.toastService.showToast(
            'Data retrieved',
            'success'
          );
        },
        error: (err) => {
          this.toastService.showToast(err, 'danger');
        }
      });
  }

  openEvent(url: string) {
    window.open(url, '_blank');
  }
}
